#!/bin/bash
COMMIT_SHA=$(git log -1 --format='%h')
BASE_SHA="156355c"

cat << JSON_PAYLOAD
{
  "title": "fix(ramshared): map driver internal errors to blk_status_t cleanly",
  "body": "## Resumo\nMap driver internal errors to BLK_STS_RESOURCE, BLK_STS_IOERR, and BLK_STS_NOTSUPP cleanly in drivers/block/ramshared/queue.c.\n\n## Commits\n| Commit | O que fez | Por que fez | Detalhes |\n|---|---|---|---|\n| ${COMMIT_SHA} | mapped errnos to blk_status_t | Map internal errors cleanly to blk_status_t | Used check_shl_overflow, fail-fast validations |\n\n## Labels\ntype:kernel\narea:upstream\n\n## Validacao\n\`\`\`bash\ncat << 'EOF' > patch_queue.js\nconst fs = require('fs');\n\nlet content = fs.readFileSync('drivers/block/ramshared/queue.c', 'utf8');\n\nconst helper = \`static blk_status_t ramshared_errno_to_blk_status(int err)\n{\n\\tswitch (err) {\n\\tcase -ENOMEM:\n\\t\\treturn BLK_STS_RESOURCE;\n\\tcase -ENOTSUPP:\n\\tcase -EOPNOTSUPP:\n\\t\\treturn BLK_STS_NOTSUPP;\n\\tcase -EINVAL:\n\\tcase -ERANGE:\n\\tcase -EIO:\n\\tdefault:\n\\t\\treturn BLK_STS_IOERR;\n\\t}\n}\n\n\`;\n\ncontent = content.replace('static blk_status_t ramshared_process_bio', helper + 'static blk_status_t ramshared_process_bio');\n\ncontent = content.replace(\n\`\\tif (unlikely(!IS_ALIGNED(pos, RAMSHARED_SECTOR_SIZE) ||\n\\t\\t     !IS_ALIGNED(bio->bi_iter.bi_size, RAMSHARED_SECTOR_SIZE))) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Unaligned bio: pos=%lld, len=%u\\\\n\",\n\\t\\t\\t\\t    pos, bio->bi_iter.bi_size);\n\\t\\treturn BLK_STS_IOERR;\n\\t}\`,\n\`\\tif (unlikely(!IS_ALIGNED(pos, RAMSHARED_SECTOR_SIZE) ||\n\\t\\t     !IS_ALIGNED(bio->bi_iter.bi_size, RAMSHARED_SECTOR_SIZE))) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Unaligned bio: pos=%lld, len=%u\\\\n\",\n\\t\\t\\t\\t    pos, bio->bi_iter.bi_size);\n\\t\\treturn ramshared_errno_to_blk_status(-EINVAL);\n\\t}\`\n);\n\ncontent = content.replace(\n\`\\tif (unlikely(pos > rs_dev->dma.size ||\n\\t\\t     bio->bi_iter.bi_size > rs_dev->dma.size - pos ||\n\\t\\t     pos + bio->bi_iter.bi_size > rs_dev->capacity_bytes)) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Bio bounds violation: pos=%lld, len=%u, cap=%llu\\\\n\",\n\\t\\t\\t\\t    pos, bio->bi_iter.bi_size,\n\\t\\t\\t\\t    rs_dev->capacity_bytes);\n\\t\\treturn BLK_STS_IOERR;\n\\t}\`,\n\`\\tif (unlikely(pos > rs_dev->dma.size ||\n\\t\\t     bio->bi_iter.bi_size > rs_dev->dma.size - pos ||\n\\t\\t     pos + bio->bi_iter.bi_size > rs_dev->capacity_bytes)) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Bio bounds violation: pos=%lld, len=%u, cap=%llu\\\\n\",\n\\t\\t\\t\\t    pos, bio->bi_iter.bi_size,\n\\t\\t\\t\\t    rs_dev->capacity_bytes);\n\\t\\treturn ramshared_errno_to_blk_status(-ERANGE);\n\\t}\`\n);\n\n\ncontent = content.replace(\n\`\\tif (unlikely(!rs_dev || !rs_dev->dma.cpu_addr))\n\\t\\treturn BLK_STS_IOERR;\n\n\\tif (unlikely(check_shl_overflow((loff_t)blk_rq_pos(rq), RAMSHARED_SECTOR_SHIFT, &pos)))\n\\t\\treturn BLK_STS_IOERR;\n\n\\tif (unlikely(!IS_ALIGNED(pos, RAMSHARED_SECTOR_SIZE) ||\n\\t\\t     !IS_ALIGNED(len, RAMSHARED_SECTOR_SIZE))) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Unaligned I/O request: pos=%lld, len=%zu\\\\n\",\n\\t\\t\\t\\t    pos, len);\n\\t\\treturn BLK_STS_IOERR;\n\\t}\n\n\\tif (unlikely(pos > rs_dev->dma.size ||\n\\t\\t     len > rs_dev->dma.size - pos ||\n\\t\\t     pos + len > rs_dev->capacity_bytes)) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"I/O bounds violation: pos=%lld, len=%zu, cap=%llu, mapped=%zu\\\\n\",\n\\t\\t\\t\\t    pos, len, rs_dev->capacity_bytes,\n\\t\\t\\t\\t    rs_dev->dma.size);\n\\t\\treturn BLK_STS_IOERR;\n\\t}\`,\n\`\\tif (unlikely(!rs_dev || !rs_dev->dma.cpu_addr))\n\\t\\treturn ramshared_errno_to_blk_status(-EIO);\n\n\\tif (unlikely(check_shl_overflow((loff_t)blk_rq_pos(rq), RAMSHARED_SECTOR_SHIFT, &pos)))\n\\t\\treturn ramshared_errno_to_blk_status(-ERANGE);\n\n\\tif (unlikely(!IS_ALIGNED(pos, RAMSHARED_SECTOR_SIZE) ||\n\\t\\t     !IS_ALIGNED(len, RAMSHARED_SECTOR_SIZE))) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"Unaligned I/O request: pos=%lld, len=%zu\\\\n\",\n\\t\\t\\t\\t    pos, len);\n\\t\\treturn ramshared_errno_to_blk_status(-EINVAL);\n\\t}\n\n\\tif (unlikely(pos > rs_dev->dma.size ||\n\\t\\t     len > rs_dev->dma.size - pos ||\n\\t\\t     pos + len > rs_dev->capacity_bytes)) {\n\\t\\tdev_err_ratelimited(rs_dev->dev,\n\\t\\t\\t\\t    \"I/O bounds violation: pos=%lld, len=%zu, cap=%llu, mapped=%zu\\\\n\",\n\\t\\t\\t\\t    pos, len, rs_dev->capacity_bytes,\n\\t\\t\\t\\t    rs_dev->dma.size);\n\\t\\treturn ramshared_errno_to_blk_status(-ERANGE);\n\\t}\`\n);\n\nfs.writeFileSync('drivers/block/ramshared/queue.c', content);\nEOF\nnode patch_queue.js\ncurl -sL https://raw.githubusercontent.com/torvalds/linux/master/scripts/checkpatch.pl -o checkpatch.pl\nchmod +x checkpatch.pl\ntouch .checkpatch.conf\n./checkpatch.pl --no-tree -f drivers/block/ramshared/queue.c\ngit add drivers/block/ramshared/queue.c\ngit commit -m \"fix(ramshared): map driver internal errors to blk_status_t cleanly\n\nImplement ramshared_errno_to_blk_status() to map semantic driver errnos (-ENOMEM,\n-ENOTSUPP, -ERANGE, -EINVAL) to their corresponding blk_status_t (BLK_STS_RESOURCE,\nBLK_STS_NOTSUPP, BLK_STS_IOERR) instead of returning hardcoded BLK_STS_IOERR everywhere.\n\nRollback trigger: If driver I/O request fails inconsistently or crashes system.\"\nrm patch_queue.js checkpatch.pl .checkpatch.conf\n\`\`\`\n\n## Rollback trigger\nIf driver I/O request fails inconsistently or crashes system."
}
JSON_PAYLOAD
